#!/usr/bin/env python3
"""Validation script for pipeline outputs."""

import json
import os
import pandas as pd

OUTPUTS_DIR = "outputs"
VALIDATION_SUMMARY = os.path.join(OUTPUTS_DIR, "t14_validation_summary.json")

# Files to validate with their expected columns and minimum rows
VALIDATION_CONFIG = {
    "t01_selected_indicators.csv": {
        "expected_columns": ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"],
        "min_rows": 1
    },
    "t05_clean_stops.csv": {
        "expected_columns": ["stop_id", "stop_name", "stop_lat", "stop_lon"],
        "min_rows": 1
    },
    "t08_pois_clean.csv": {
        "expected_columns": ["qid", "label", "poi_type", "latitude", "longitude", "source"],
        "min_rows": 1
    },
    "t10_accessibility_scores.csv": {
        "expected_columns": ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"],
        "min_rows": 1
    },
    "t13_city_clusters.csv": {
        "expected_columns": ["city_id", "cluster_id", "cluster_name", "population"],
        "min_rows": 1
    }
}

def validate_file(file_path, config):
    """Validate a single file against its configuration."""
    results = []

    # Check if file exists
    if not os.path.exists(file_path):
        results.append({
            "check_name": f"{os.path.basename(file_path)}_exists",
            "passed": False,
            "message": f"File does not exist: {file_path}"
        })
        return results

    # Check if file is non-empty
    if os.path.getsize(file_path) == 0:
        results.append({
            "check_name": f"{os.path.basename(file_path)}_non_empty",
            "passed": False,
            "message": f"File is empty: {file_path}"
        })
        return results

    # Read the file
    try:
        df = pd.read_csv(file_path)
    except Exception as e:
        results.append({
            "check_name": f"{os.path.basename(file_path)}_readable",
            "passed": False,
            "message": f"Error reading file: {str(e)}"
        })
        return results

    # Check minimum rows
    if len(df) < config["min_rows"]:
        results.append({
            "check_name": f"{os.path.basename(file_path)}_has_data",
            "passed": False,
            "message": f"File has fewer than {config['min_rows']} rows (has {len(df)})"
        })
    else:
        results.append({
            "check_name": f"{os.path.basename(file_path)}_has_data",
            "passed": True,
            "message": f"File has {len(df)} rows (minimum: {config['min_rows']})"
        })

    # Check expected columns
    missing_columns = set(config["expected_columns"]) - set(df.columns)
    if missing_columns:
        results.append({
            "check_name": f"{os.path.basename(file_path)}_has_columns",
            "passed": False,
            "message": f"Missing columns: {missing_columns}"
        })
    else:
        results.append({
            "check_name": f"{os.path.basename(file_path)}_has_columns",
            "passed": True,
            "message": f"All expected columns present: {config['expected_columns']}"
        })

    return results

def main():
    """Main validation function."""
    all_results = []

    for filename, config in VALIDATION_CONFIG.items():
        file_path = os.path.join(OUTPUTS_DIR, filename)
        results = validate_file(file_path, config)
        all_results.extend(results)

    # Write results to JSON
    os.makedirs(os.path.dirname(VALIDATION_SUMMARY), exist_ok=True)
    with open(VALIDATION_SUMMARY, 'w') as f:
        json.dump(all_results, f, indent=2)

    print(f"Validation complete. Results written to {VALIDATION_SUMMARY}")

if __name__ == "__main__":
    main()
```

